// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

/**
 * Resolves collision between a ball and a brick.
 * If they collide, the brick is destroyed and the ball is bounced back.
 * Returns true if a collision occurred.
 */
export function resolveBrickCollision(ball, brick) {
  if (!collides(ball, brick)) return false;

  // Calculate overlap on each axis
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

  if (overlapX < overlapY) {
    // Side hit: flip vx and push out
    ball.vx = -ball.vx;
    if (ball.x + ball.r <= brick.x + (brick.w * 0.1)) {
       // This is too simplistic, let's use the actual side hit logic
    }
  }
  return true;
}

