import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  resolveBrickCollision,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- ISSUE #1 TESTS ---

test('resolveBrickCollision: flip vy on top hit', () => {
  const ball = { x: 100, y: 85, r: 7, vx: 0, vy: -100 };
  const brick = { x: 80, y: 90, w: 40, h: 20 }; // ball is hitting from top
  // Ball bottom: 85+7 = 92. Brick top: 90. OverlapY: 2.
  // Ball x range: [93, 92]. Brick x range: [80, 120]. OverlapX: 7 (min of 92-80=12 and 120-93=27)
  // Wait, let's be more precise.
  // Ball x=100, r=7 => x bounds [93, 107]. Brick x bounds [80, 120]. 
  // dx1 = 107 - 80 = 27. dx2 = 120 - 93 = 27. overlapX = 27.
  // Ball y=85, r=7 => y bounds [78, 92]. Brick y bounds [90, 110].
  // dy1 = 92 - 90 = 2. dy2 = 110 - 78 = 32. overlapY = 2.
  // overlapY < overlapX (2 < 27), so it's a top/bottom hit.
  // dy1 < dy2 (2 < 32), so it's a top hit. vy should flip and ball should be pushed up.

  const initialVy = ball.vy;
  const collided = resolveBrickCollision(ball, brick);
  assert.equal(collided, true);
  assert.equal(ball.vy, -initialVy);
  assert.ok(ball.y < 85, 'ball should be pushed out of brick');
});

test('resolveBrickCollision: flip vx on left hit', () => {
  const ball = { x: 75, y: 100, r: 7, vx: 100, vy: 0 };
  const brick = { x: 80, y: 90, w: 40, h: 20 }; 
  // Ball x bounds [68, 82]. Brick x bounds [80, 120].
  // dx1 = 82 - 80 = 2. dx2 = 120 - 68 = 52. overlapX = 2.
  // Ball y bounds [93, 107]. Brick y bounds [90, 110].
  // dy1 = 107 - 90 = 17. dy2 = 110 - 93 = 17. overlapY = 17.
  // overlapX < overlapY (2 < 17), so it's a side hit.
  // dx1 < dx2 (2 < 52), so it's a left hit. vx should flip and ball should be pushed left.

  const initialVx = ball.vx;
  const collided = resolveBrickCollision(ball, brick);
